package service;

import crypto.PasswordHasher;
import store.CredentialHistoryStore;

import java.util.List;

/** Answers "has this account used that password recently?" against the stored hashes. */
public class PasswordHistoryGuard {
    private final CredentialHistoryStore history;
    private final PasswordHasher hasher;

    public PasswordHistoryGuard(CredentialHistoryStore history, PasswordHasher hasher) {
        this.history = history;
        this.hasher = hasher;
    }

    public boolean usedRecently(String accountId, String candidate, int window) {
        if (window <= 0) {
            return false;
        }
        List<String> recent = history.recent(accountId, window);
        for (String hash : recent) {
            if (hasher.matches(candidate, hash)) {
                return true;
            }
        }
        return false;
    }

    public void remember(String accountId, String passwordHash) {
        history.append(accountId, passwordHash);
    }
}
package service;

import crypto.PasswordHasher;
import domain.Account;
import domain.PasswordPolicy;
import domain.PolicyViolation;
import store.AccountStore;
import store.SessionStore;

import java.time.Clock;
import java.util.ArrayList;
import java.util.List;

/** Password change (by the user) and password reset (by an administrator). */
public class PasswordService {
    private final AccountStore accounts;
    private final SessionStore sessions;
    private final PasswordHasher hasher;
    private final PasswordHistoryGuard historyGuard;
    private final PasswordPolicy policy;
    private final Clock clock;

    public PasswordService(AccountStore accounts, SessionStore sessions, PasswordHasher hasher,
                           PasswordHistoryGuard historyGuard, PasswordPolicy policy, Clock clock) {
        this.accounts = accounts;
        this.sessions = sessions;
        this.hasher = hasher;
        this.historyGuard = historyGuard;
        this.policy = policy;
        this.clock = clock;
    }

    public void change(String accountId, String currentPassword, String newPassword) {
        Account account = accounts.findById(accountId)
                .orElseThrow(() -> ValidationException.of(404, "account not found"));
        if (!hasher.matches(currentPassword, account.passwordHash())) {
            throw ValidationException.of(403, "current password is incorrect");
        }
        apply(account, newPassword);
    }

    public void adminReset(String accountId, String newPassword) {
        Account account = accounts.findById(accountId)
                .orElseThrow(() -> ValidationException.of(404, "account not found"));
        apply(account, newPassword);
        sessions.removeAllFor(accountId);
    }

    private void apply(Account account, String newPassword) {
        List<String> problems = new ArrayList<>();
        for (PolicyViolation v : policy.check(account.username(), newPassword)) {
            problems.add(v.message());
        }
        if (problems.isEmpty() && historyGuard.usedRecently(account.id(), newPassword, policy.reuseWindow())) {
            problems.add(PolicyViolation.RECENTLY_USED.message());
        }
        if (!problems.isEmpty()) {
            throw new ValidationException(422, problems);
        }
        String hash = hasher.hash(newPassword);
        accounts.save(account.withPassword(hash, clock.instant()));
        historyGuard.remember(account.id(), hash);
    }
}
package config;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Properties;

/** Application settings: config/app.properties, overridden by JVM system properties. */
public final class Settings {
    private static final Path DEFAULT_FILE = Path.of("config", "app.properties");

    private final Properties values;

    private Settings(Properties values) {
        this.values = values;
    }

    public static Settings load() {
        return load(DEFAULT_FILE);
    }

    public static Settings load(Path file) {
        Properties props = new Properties();
        if (Files.isRegularFile(file)) {
            try (InputStream in = Files.newInputStream(file)) {
                props.load(in);
            } catch (IOException e) {
                throw new IllegalStateException("cannot read " + file, e);
            }
        }
        for (String name : System.getProperties().stringPropertyNames()) {
            if (name.startsWith("password.") || name.startsWith("session.") || name.startsWith("profile.")) {
                props.setProperty(name, System.getProperty(name));
            }
        }
        return new Settings(props);
    }

    public static Settings of(Properties props) {
        Properties copy = new Properties();
        copy.putAll(props);
        return new Settings(copy);
    }

    public String value(String key, String fallback) {
        String v = values.getProperty(key);
        return v == null || v.isBlank() ? fallback : v.trim();
    }

    public int intValue(String key, int fallback) {
        String v = value(key, null);
        if (v == null) {
            return fallback;
        }
        try {
            return Integer.parseInt(v);
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    public boolean boolValue(String key, boolean fallback) {
        String v = value(key, null);
        return v == null ? fallback : Boolean.parseBoolean(v);
    }
}
